import copy,json,math
from work import evaluate

p={"base_unit":"m","units":{"m":1,"cm":0.01},"unique":True}
r={"rows":[
 {"id":"a","amount":2,"unit":"cm","extra":1},
 {"id":"","amount":-1,"unit":"bad"},
 {"id":"b","amount":True},
 {"id":"c","amount":float("inf")},
 {"id":"d","amount":1,"unit":[]},
 {"id":"a","amount":3},
 {"id":"e","amount":0}
]}
r0=copy.deepcopy(r); p0=copy.deepcopy(p)
out=evaluate(r,p)
assert out=={"ok":False,"records":[],"errors":[{"row":1,"cause":"id"},{"row":2,"cause":"amount"},{"row":3,"cause":"amount"},{"row":4,"cause":"unit"},{"row":5,"cause":"duplicate"}]}
assert r==r0 and p==p0
assert evaluate({"rows":[{"id":"x","amount":5},{"id":"x","amount":7}]},{**p,"unique":False})=={"ok":True,"records":[{"id":"x","amount":5},{"id":"x","amount":7}],"errors":[]}
assert evaluate({"rows":[{"id":"x","amount":-1},{"id":"x","amount":2}]},p)=={"ok":False,"records":[],"errors":[{"row":0,"cause":"amount"}]}
requests=json.load(open("requests.json")); policy=json.load(open("policy.json")); report=json.load(open("report.json"))
assert report==[evaluate(req,policy) for req in requests]
compile(open("work.py").read(),"work.py","exec")
print("all validation, mutation, exact-shape, report, and compile checks passed")

